function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4000);}
function normalizeLegacyUrl(){
 const url=new URL(location.href);
 if(url.hash.startsWith('#/')){url.pathname=url.hash.slice(1);url.hash='';}
 else if(['/prototype','/prototype/','/prototype/index.html'].includes(url.pathname))url.pathname='/';
 if(url.pathname==='/home'||url.pathname==='/home/')url.pathname='/';
 if(url.href!==location.href)history.replaceState(null,'',url);
}
function route(){return (location.pathname.replace(/^\/|\/$/g,'')||'home').split('/');}
function routeChanged(){if(advisorDialog.open)advisorDialog.close();if(cartDialog.open)cartDialog.close();render();window.scrollTo({top:0,left:0,behavior:'instant'});if(!cartDialog.open)document.querySelector('#main')?.focus({preventScroll:true});}
function navigate(path){const url=new URL(path.startsWith('/')?path:'/'+path,location.origin);if(url.pathname==='/home')url.pathname='/';history.pushState(null,'',url);captureReferral(state,url.searchParams.get('ref'));routeChanged();}

function count(){return Object.values(state.cart).reduce((n,v)=>n+v,0);}
function header(){const current=route()[0];const links=[['catalog','Bộ sưu tập trà'],['story','Câu chuyện Thịnh An'],['gifts','Quà doanh nghiệp'],['journal','Báo chí & sự kiện']];return `<header class="site-header"><a class="brand" href="/" aria-label="Thịnh An — Trang chủ"><img src="/thinh-an.svg" alt="Thịnh An Teas"><span>THỊNH AN<small>TINH HOA TRÀ VIỆT</small></span></a><nav id="store-nav" aria-label="Điều hướng chính">${links.map(([path,label])=>`<a href="/${path}" ${current===path||(path==='catalog'&&current==='product')?'class="active" aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="header-actions"><a class="icon-button" href="/catalog" aria-label="Tìm trà">${icon('search')}</a><button class="cart-open" data-action="cart" aria-label="Giỏ hàng, ${count()} sản phẩm">${icon('bag')}<span>Giỏ hàng</span><b class="cart-count">${count()}</b></button><button class="icon-button menu-toggle" data-action="menu" aria-label="Mở menu" aria-expanded="false" aria-controls="store-nav">${icon('menu')}</button></div></header>`;}

