function eventCards(items=events){return `<div class="event-grid">${items.map(e=>`<a href="/journal/${e.id}">${image(e.image,e.caption)}<small>NHẬT KÝ SỰ KIỆN · ${articleDate(e)}</small><h3>${esc(e.title)}</h3><p>${esc(e.intro)}</p><span class="text-link">Đọc câu chuyện ${icon('arrow')}</span></a>`).join('')}</div>`;}
function eventPage(id){const e=events.find(e=>e.id===id);if(!e)return `<section class="empty page-empty"><h1>Chưa tìm thấy bài viết.</h1>${btn('Về báo chí & sự kiện','/journal')}</section>`;return `<article class="event-article"><nav class="breadcrumb" aria-label="Đường dẫn"><a href="/">Trang chủ</a><span>/</span><a href="/journal">Báo chí & sự kiện</a><span>/</span><span aria-current="page">Nhật ký Thịnh An</span></nav><header class="event-article-heading"><span class="eyebrow">NHẬT KÝ THỊNH AN · <time datetime="${e.date}">${articleDate(e)}</time></span><h1>${esc(e.title)}</h1><p>${esc(e.intro)}</p></header><figure class="event-article-cover">${image(e.image,e.caption,'',true)}<figcaption>${esc(e.caption)}</figcaption></figure><div class="event-article-body"><h2>${esc(e.heading)}</h2>${e.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}<figure>${image(e.gallery,e.galleryCaption)}<figcaption>${esc(e.galleryCaption)}</figcaption></figure><div class="event-article-cta"><span class="eyebrow">TIẾP NỐI CÂU CHUYỆN</span><h2>Mang một chút hương trà về nhà.</h2><p>Khám phá các dòng trà Thịnh An hoặc trao đổi nhu cầu quà tặng cho doanh nghiệp.</p><div class="button-row">${btn('Khám phá trà','/catalog')}<a class="text-link" href="/gifts">Quà doanh nghiệp ${icon('arrow')}</a></div></div></div></article><section class="section"><div class="section-heading"><div><span class="eyebrow">NHỮNG ĐIỂM DỪNG KHÁC</span><h2>Tiếp tục <em>hành trình.</em></h2></div><a class="text-link" href="/journal">Tất cả bài viết ${icon('arrow')}</a></div>${eventCards(events.filter(x=>x.id!==id))}</section>`;}
function journal(id){if(id)return eventPage(id);return `<section class="page-intro"><span class="eyebrow">BÁO CHÍ & SỰ KIỆN</span><h1>Câu chuyện trà.<br>Những cuộc <em>hội ngộ.</em></h1><p>Theo chân Thịnh An qua các hoạt động, sự kiện và góc nhìn từ báo chí.</p></section><section class="section"><div class="section-heading"><div><span class="eyebrow">NHẬT KÝ THỊNH AN</span><h2>Trên hành trình <em>gặp gỡ.</em></h2></div></div>${eventCards()}</section>${pressArchive()}`;}

